INSERT INTO `mod_lore_codex_entry` (`ID`, `Kind`, `Zone`, `SortOrder`, `Faction`, `RequiredState`, `Title`, `Body`, `Sources`) VALUES
(352000, 0, 3520, 0, 0, 0, 'Shadowmoon Valley', 'Shadowmoon Valley lies in the far southeast of Outland, a land of ash, black rock and rivers of green fel lava under a dim and smoky sky. The orcs of the Shadowmoon clan once honored their ancestors here, and at its eastern edge the draenei raised the Temple of Karabor, one of their holiest sites. Both were lost to the Horde. Gul''dan''s warriors took Karabor and the Shadow Council made it their seat, and the warlock raised the volcano at the valley''s center in a ritual that severed the orcs from the elements of Draenor. The temple, now called the Black Temple, is the throne of Illidan Stormrage, and his servants, fel orcs and naga, Broken and blood elves, hold the valley in his name. The Burning Legion bombards it from Legion Hold. Against them stand the Wildhammer dwarves, the Horde''s Kor''kron, and the Aldor and Scryers of Shattrath, while the Netherwing drakes struggle against the Dragonmaw orcs who enslave them.', 'warcraft.wiki.gg/wiki/Shadowmoon_Valley (clan named after the valley, ancestor worship, Temple of Karabor as spiritual capital, Hand of Gul''dan raised to sever the link to the elements, Black Temple as Shadow Council base, Illidan''s headquarters, settlements); quest 10642 description (ancestral grounds of the Shadowmoon orcs); quest 10635 description (Gul''dan''s Horde defeated the draenei of Karabor); npc_text 10250 (Torlok: Gul''dan severed the tie between orcs and spirits); quest 10568 description (Gul''dan raised the volcano); creature_template subnames ''Servant of Illidan'' on Ashtongue, Coilskar, Shadowmoon fel orcs; Eclipsion blood elves; quests 10562, 10595 (infernals from Legion Hold); warcraft.wiki.gg/wiki/Black_Temple (sacred draenei site; no coastal setting in BC)'),
(352001, 1, 3520, 1, 0, 0, 'Wildhammer Stronghold', 'Wildhammer Stronghold stands in the southwest of the valley, the fortress of Kurdran Wildhammer, thane of the Wildhammer in Outland, and his gryphon riders. It is a hard place to hold. Infernals fall on its walls from Legion Hold to the northwest, Illidan''s minions press from the other side, and Wing Commander Nuainn''s riders have fought so long without relief that they are ragged with exhaustion. The ground itself is restless: the stronghold was built over the ancestral grounds of the Shadowmoon orcs, and the spirits of the old clan, dormant for nearly twenty years, now wander its courtyards. Zorus the Judicator studies them, while the gnome Gnomus, an inventor turned gourmand, dreams only of food that never cools.', 'npc_text 10349 (Nuainn: the Legion on one side and Illidan''s minions on the other); quest 10562 description (Legion Hold to the northwest, men ragged and exhausted); quest 10642 description (ancestral grounds, spirits dormant nearly twenty years); quest 10643 (Shadowmoon harbingers infesting the stronghold); quests 10661, 10672 (Gnomus, food that cooks itself and stays hot; inventor of the arcano-scorps); npc_text 9805 (Kurdran holds audiences in the stronghold); zone_areas: Kurdran 21330, Nuainn 21357, Zorus 21774, Gnomus 21777 stand in area 3745'),
(352002, 1, 3520, 2, 0, 0, 'Shadowmoon Village', 'Shadowmoon Village is the Horde''s outpost in the northwest of the valley, held by Overlord Or''barokh and the elite Kor''kron guard. Like the dwarves to the south it lives under the Legion''s guns: infernals from Legion Hold to the southwest rain on its walls, and Blood Guard Gulmok drafts every able fighter onto the line. The village is haunted as well. Chief Apothecary Hildagard has crafted goggles that reveal the ghosts of Shadowmoon zealots drifting among the buildings, and what she learns from them leaves her badly shaken. Nearby, the blood elf Researcher Tiorus studies the heat-proof diemetradons of the lava flows with probes built by his former partner, the gnome Gnomus, who resents it.', 'quest 10595 description (Legion Hold to the southwest, the elite Kor''kron guard, every able-bodied fighter drafted); quests 10624, 10625 (Spectrecles, Shadowmoon Zealots in the village, Hildagard''s shock at Gorefiend''s name); quests 10660, 10672 (Tiorus, diemetradons, arcano control units crafted by Gnomus); quest 10678 description (Gnomus: Tiorus continued their research using MY inventions); zone_areas: Or''barokh 21769, Gulmok 21359, Hildagard 21772, Tiorus 21770, Kor''kron Defender, Shadowmoon Zealot 21788 in area 3744'),
(352003, 1, 3520, 3, 0, 0, 'Legion Hold', 'Legion Hold is the Burning Legion''s fortress in western Shadowmoon, the source of the infernals that pound both the Wildhammer and the Horde outposts. Warbringer Razuun directs its war in the name of Doom Lord Kazzak, and his order to the hold''s commander was plain: destroy the orcish and dwarven strongholds with all haste. Terrormasters and Shadow Council warlocks guard the stockpiled infernals, and the pit lords Makazradon and Morgroron bear glaives forged to slay demons. Beside the hold, the Fetid Pool festers around the wreckage of a fallen fel reaver. A teleporter in the hold leads to Invasion Point: Cataclysm, high in the northern mountains, where the Legion masses still more infernals under the guard of fel reaver sentinels.', 'creature_text 21502 (Image of Warbringer Razuun: Kazzak will be pleased, destroy the orcish and dwarven strongholds) and 21633 (Deathbringer Jovaan); quest 10563 description (the Legion stocks its infernals at the hold); quest 10626 description (Makazradon and Morgroron equipped with anti-demon weapons); quests 10564, 10572 (fel reaver power core and wreckage at the Fetid Pool); quests 10589, 10604 (Invasion Point: Cataclysm, infernal staging area in the northern mountains, reached by a teleporter at Legion Hold); zone_areas: Terrormaster 21314, Shadow Council Warlock 21302, Morgroron 21500, Makazradon 21501 in 3743; Mutant Horror in 3940; Fel Reaver Sentinel 21949 in 3943'),
(352004, 1, 3520, 4, 0, 0, 'The Deathforge', 'The Deathforge is a Shadow Council foundry dug into the rock between the two outposts, where infernals are made as fast as the Legion can hurl them. Mo''arg smiths work the forges, and in a summoning chamber below ground the warlocks call up the corrupted elementals that become the burning hearts of the infernals. Two scouting parties watch from the heights, the dwarves of Deathforge Tower and the orcs of Slag Watch, under strict orders to observe and not to fight. Each lost one of its own inside: the Wildhammer Flanis Swiftwing, who volunteered to spy, and the orc Kagrosh, who wanted to be a hero. Neither came back, and their bodies lie where the forge''s keepers left them.', 'quests 10573, 10599 (Shadow Council producing infernals in the Deathforge; Deathforge Tower northwest of Wildhammer, Slag Watch southeast of the village); quests 10585, 10602 (summoning chamber below ground, elementals that form the core of the infernals; mo''arg smiths and tinkerers); quests 10582, 10600 (orders to observe, not engage); quests 10583, 10601; npc_text 10427 and 10446 (Flanis''s and Kagrosh''s corpses)'),
(352005, 1, 3520, 5, 0, 0, 'Illidari Point', 'Illidari Point lies in the southwest, between Legion Hold and Wildhammer Stronghold. It is the proving ground for Illidan''s demons, those who abandoned the Burning Legion to serve the Betrayer, and satyrs, shadowstalkers and succubi gather there under his lieutenant Lothros. Succubi led by Painmistress Gabrissa work their rituals around a rune ringed by hovering crystals, and hidden in the ether at the back of the point lurks a creature called Veneratus the Many. Here Ar''tor, the youngest son of Oronok Torn-heart, came hunting a piece of the Cipher of Damnation. He was found dead, his body held in the air above the rune by beams from the demonic crystals.', 'quest 10527 description (location; proving grounds for demons that left the Legion to join the Betrayer); quest 10668 description (Lothros, Illidan''s lieutenant at Illidari Point); quests 10528, 10540 (crystals, succubi rituals, Gabrissa, Veneratus hidden in the ether); quest 10527 reward text, npc_text 10323 (Ar''tor''s body suspended); zone_areas: Illidari Satyr, Shadowstalker, Painmistress Gabrissa 21309 in 3752; Lothros 21928 position in 3752'),
(352006, 1, 3520, 6, 0, 0, 'Sketh''lon and the Magma Fields', 'The Sketh''lon arakkoa once camped in western Shadowmoon. When the Horde massed under Gul''dan they planned to strike at him first, and the warlock answered with a spell that destroyed their camps and twisted their spirits. Their ruins remain: the Sketh''lon Wreckage northwest of the Deathforge, and the Sketh''lon Base Camp to the south, east of Wildhammer Stronghold. Their ghosts linger as the Dark Conclave, and they prey on the orc peons sent to cut wood among the ruins, draining their lives to feed their magic. Between the two outposts the road crosses the Magma Fields, where lava flows through cracks in the ground and felfire diemetradons bask in the heat.', 'quest 10777 description (arakkoa sought to strike against Gul''dan, his spell destroyed their camps and twisted their spirits); quests 10569, 10760, 10780 (locations; spirits prey on peon work groups, draining their life); quests 10759, 10761 (road through the Magma Fields between the outposts); quest 10660 (felfire diemetradons where lava flows through the cracks); zone_areas: Dark Conclave Hawkeye 21386 in 3933, Scorncrow 21385 in 3932, Felfire Diemetradon in 3949'),
(352007, 1, 3520, 7, 0, 0, 'The Hand of Gul''dan', 'The Hand of Gul''dan is the great volcano at the center of the valley, raised by the warlock Gul''dan in the ritual that tore the orcs away from the elements. Fel lava still pours down its sides, and its lava long ago buried the draenei village of Baa''ri. On its flanks the Fel Pits seethe with enraged spirits of fire and earth, and the Ashtongue Corruptors Eykenen and Uylaru, once shaman who now defile the elements they revered, tend corrupt totems among them. The Scalding Pools lie near the summit. Spectral riders, the Ghostriders of Karabor, circle the mountain on the roads around its base, and the fel beast Uvuros, wanted dead by both outposts, prowls its slopes.', 'quest 10568 description (Gul''dan raised the volcano, Baa''ri buried under lava); warcraft.wiki.gg/wiki/Shadowmoon_Valley (Hand of Gul''dan raised to sever the orcs'' link to the elements); quests 10574, 10458 (Eykenen and Uylaru at the Fel Pits; enraged fire and earth spirits); quest 10679 (Scalding Pools near the top of the Hand); quest 10636 description (Ghostriders of Karabor ride the roads encircling the Hand); quests 10647, 10648 (Uvuros last seen at the Hand of Gul''dan)'),
(352008, 1, 3520, 8, 0, 0, 'The Altar of Damnation', 'On the western outskirts of the Hand of Gul''dan stands the Altar of Damnation, where Gul''dan spoke the words that shattered this land. The moment has left its mark. A memory of the warlock still stands at the altar among the kneeling spirits of the damned, and beside him linger remnants of his hate, greed, malice, pride and corruption. Earthmender Torlok and Earthmender Gorboto of the Earthen Ring keep watch there, seeking to commune with the tortured elements. Gul''dan was not content to destroy the draenei, Torlok says: he razed Draenor itself and siphoned off its energies for his war, and all that is left here are the remnants of his madness.', 'quest 10451 log text (Altar of Damnation on the western outskirts of the Hand of Gul''dan); quest 10588 description (the memory of Gul''dan stands at the altar); npc_text 10315 (Oronok: spirits of the damned kneeling in prayer); creature_template 22094, 22437, 22438, 22439, 22440 (Remnants of Hate, Malice, Greed, Corruption, Pride, Aspect of Gul''dan); creature_text 17008 (Gul''dan''s vision lines); npc_text 10250 (Torlok); zone_areas: Torlok 21024, Gorboto 21026, Gul''dan 17008 in 3928'),
(352009, 1, 3520, 9, 0, 0, 'Coilskar Point', 'Coilskar Point and the cistern to its east are the lair of the Coilskar naga, servants of Illidan, who have seized the only clean water left in Shadowmoon Valley. They foul it for their own ends, and the agitated pools around their villages howl with the anguish of enraged water spirits. The earthmender Wilda came seeking the source of the spirits'' distress and was taken prisoner, held in a watery cell beside other captive spirits. Lady Shav''rar commands at the point, and Coilskar sorceresses guard the cistern. It was here, too, that the naga hid one fragment of the Cipher of Damnation in their chests, a secret Grom''tor, eldest son of Oronok, beat out of a Coilskar commander.', 'quest 10480 description (naga took control of the only clean water supply; agitated water pockets, enraged water spirits); quest 10451 description and creature_text 21027 (Wilda''s capture, watery prison, other prisoners); quests 10521, 10522; creature_text 21291, 21295 (Grom''tor interrogates the Coilskar Commander; fragment in a chest at Coilskar Point or Cistern); zone_areas: Lady Shav''rar 20684, Coilskar Commander 21295 in 3750'),
(352010, 1, 3520, 10, 0, 0, 'Oronok''s Farm', 'High on the Shattered Shelf above Coilskar Cistern, a weathered orc keeps a campfire and a herd of trained felboars. He calls himself Oronok Torn-heart, hermit and farmer, and his boars root tubers out of the hard earth of the Shattered Plains below. The plains are not kind to farmers: ravenous flayers from a nest to the northeast prey on his animals, and a flayer matriarch guards their eggs. Oronok invites travelers to warm themselves by his fire and warns them of the beasts of the shelf. Few guess that the farmer''s life is a disguise, or that this quiet old orc once stood at Gul''dan''s side.', 'quest 10513 log text (Shattered Shelf, north of Coilskar Cistern); quest 10514 description (felboars dig tubers on the Shattered Plains, flayers from a nest to the northeast); quest 10515 (flayer eggs); npc_text 10280 (sit by my fire, beware the ravenous beasts of the shattered shelf); quest 10519 description; npc_text 10315 (the farmer is a masquerade; lieutenant of Gul''dan); zone_areas: Oronok 21183 in 3927; Ravenous Flayer, Domesticated Felboar in 3926'),
(352011, 1, 3520, 11, 0, 0, 'Ruins of Baa''ri', 'Baa''ri was a draenei village, rich in relics of religious importance, until the Hand of Gul''dan rose and buried it under lava with its people. Now Illidan has set the Ashtongue Broken to dig it out. Scores of Ashtongue workers labor in the ruins under Illidari overseers and Akama''s lieutenant, Oronu the Elder, and handlers drive elekk demolishers through the rubble. Among the treasures they seek are the Tablets of Baa''ri, said to hold the secrets of the Temple of Karabor, and the fragments of a Medallion of Karabor, which once let the highest draenei priests pass freely into the temple. The Aldor and the Scryers both send agents to reach them first.', 'quests 10568, 10683 descriptions (village buried with its inhabitants and artifacts; Ashtongue ordered by Illidan to excavate; tablets); quests 10571, 10684 (Medallion of Karabor, Oronu the Elder as Akama''s lieutenant at Baa''ri); zone_areas: 94 Ashtongue Workers, Illidari Overseer 21808, Ashtongue Handler 21803, Elekk Demolisher 21802 in 3753'),
(352012, 1, 3520, 12, 0, 0, 'The Warden''s Cage', 'South of the Ruins of Baa''ri, the Warden''s Cage is a prison run by Akama and his Ashtongue Deathsworn, whispered among his enemies to be a torture chamber. Its most important captive is Maiev Shadowsong, the Warden who pursued Illidan to Outland, now held in a cell she swears will not keep her. A satyr named Zandras watches the prison from above its walls on Illidan''s behalf, and the demon Vagath has orders from Illidan to keep a close eye on the Warden. What the watchers do not see lies beyond the halls, through a passage hidden by stagnant water: a secret chamber where Akama takes counsel with the few he trusts.', 'quests 10575, 10686 (location south of Baa''ri; rumored torture chamber run by Akama and the Deathsworn); creature_text 21699 (Maiev: this cell won''t hold me for long); quest 10622 description (Zandras watches from above the prison walls on Illidan''s behalf); creature_text 21768 (Vagath: specific orders to keep a close watch on the Warden); quest 10628 description (hidden passage behind stagnant water); zone_areas: Akama 21700, Maiev 21699, Ashtongue Deathsworn 21701 in 3821'),
(352013, 1, 3520, 13, 0, 0, 'Altar of Sha''tar', 'The Altar of Sha''tar is the Aldor''s outpost in Shadowmoon, standing northwest of the Black Temple. From here the draenei priesthood carries its war against Illidan and the Legion to their very doorstep. Exarch Onaala, who trained as an anchorite in days when female exarchs were all but unheard of, leads the outpost, holding that courage and conviction count for more than anything else. Anchorite Ceyla studies the secrets of Karabor, Vindicator Aluumen sends fighters against the Ashtongue at Baa''ri and the fel orcs on the holy Ata''mal Terrace, and Harbinger Saronen gathers the insignias of the Legion''s officers. The Dragonmaw would gladly see the altar burned, for it blocks their way to Coilskar.', 'quest 11099 description (Aldor outpost northwest of the Black Temple; destroying it would reopen Dragonmaw lines to Coilskar); broadcast_text 19493 (Onaala: female exarchs unheard of; courage and conviction); quests 10568 (Ceyla, secrets of Karabor), 10619 and 10816 (Aluumen), 10826 (Saronen, Marks of Sargeras); zone_areas: Onaala 21860, Ceyla 21402, Aluumen 21822, Saronen 22214 in 3754'),
(352014, 1, 3520, 14, 0, 0, 'Ruins of Karabor', 'The Ruins of Karabor lie before the walls of the Black Temple, and Illidan has turned them into a training ground for demon hunters. Sunfury blood elves, soldiers of Prince Kael''thas, arrive in numbers to learn his art, dressing and fighting like Illidan himself, while Sunfury warlocks summon and bind demons for the initiates to battle. Their master is Varedis, the one blood elf of Kael''s first five to survive Illidan''s trials, and with him serve the three night elf demon hunters who trained him, Alandien, Theras and Netharel. One prisoner is too dangerous even for these lessons: the pit lord Azaloth, held banished in the ruins and seething at his captors.', 'quests 10587, 10687 (influx of Sunfury recruits, attire and fighting style like Illidan''s); quests 10637, 10688 (warlocks summon and subdue demons; Azaloth too strong, kept banished); npc_text 10492-10495 (Altruis: Kael''s five warriors, Varedis the one who succeeded, the three masters); quests 10651, 10692 (Alandien, Theras, Netharel); creature_text 21506 (Azaloth); zone_areas: Demon Hunter Supplicant/Initiate, Sunfury Warlock, Varedis 21178, Azaloth 21506 in 3756'),
(352015, 1, 3520, 15, 0, 0, 'Ata''mal Terrace', 'The Ata''mal Terrace beside the Black Temple was once one of the draenei''s holiest sites, where ata''mal crystals were used in their spiritual ceremonies. Now the fel orcs of the Shadowmoon clan, Illidan''s most feared army, hold it. Slayers, chosen and darkweavers crowd its tiers alongside shadowsworn drakonid, and they have dug special ore from the sacred ground to forge corrupted arms. The orcs keep a secret: an ata''mal crystal called the Heart of Fury, clouded in dark magic to hide it from the Sha''tar. Shadowlord Deathwail circles above the terrace, out of reach, and swears its power belongs to Illidan.', 'quest 10816 description (holy site, ata''mal crystals in spiritual ceremonies, Illidan''s most feared army); quest 10707 description (Heart of Fury guarded by fel orcs, clouded from the Sha''tar; Deathwail circles beyond reach); creature_text 22006 (Deathwail: its power belongs to Illidan); quest 11544 description (fel orcs dug special ore from the terrace and made corrupted weapons; text only, quest belongs to Quel''Danas and is not a trigger); zone_areas: Shadowmoon Slayer/Chosen/Darkweaver, Shadowsworn Drakonid 22072 in 3757'),
(352016, 1, 3520, 16, 0, 0, 'The Black Temple', 'The Black Temple was once the Temple of Karabor, the great sanctuary of the draenei. Gul''dan''s Horde took it, the Shadow Council made it their seat, and the warlock kept his private quarters inside. Later the pit lord Magtheridon ruled from it, until Illidan Stormrage drove him out with the help of Akama''s Broken and claimed the temple as his throne. The ghosts of the clerics of Karabor, murdered by Teron Gorefiend after the city fell, still roam before its walls. Now the naaru Xi''ri gathers Aldor and Scryer soldiers on the approach to the temple, and before its walls stalks Doomwalker, the fel reaver Kil''jaeden sent against its gates.', 'warcraft.wiki.gg/wiki/Black_Temple (draenei Temple of Karabor, Shadow Council seat, Magtheridon ousted by Illidan); warcraft.wiki.gg/wiki/Akama (helped destroy Magtheridon''s defenses at the Black Temple, Warcraft III); npc_text 10314 (cipher kept in Gul''dan''s private quarters inside Karabor); quest 10635 description (clerics of Karabor murdered by Gorefiend, roam in front of the Black Temple); creature_text 22862, 22864 and spawns of Lightsworn Vindicator/Seasoned Magister near Xi''ri 18528; warcraft.wiki.gg/wiki/Doomwalker (sent by Kil''jaeden to assault the gates); posarea: 3840 covers the temple grounds south of Doomwalker''s spawn (-3563, 234); warcraft.wiki.gg/wiki/Akama (Frozen Throne: helped Illidan, Kael and Vashj against Magtheridon); posarea grid around x -3400 to -3900, y 0 to 800 on map 530; areatrigger 4598 Black Temple entrance at (-3672, 318)'),
(352017, 1, 3520, 17, 0, 0, 'Netherwing Fields', 'East of the Hand of Gul''dan, fields of enormous blue crystals jut from the earth, and nether drakes wheel above them. These are the Netherwing, a young flight born of black dragon eggs that were steeped in raw nether energy. They are frightened now, too afraid of the Dragonmaw to come down even to feed, and some fall dead from exhaustion; Mordenai, himself one of the flight, does what he can to save them. Rocknail flayers, the drakes'' natural prey, swarm among the crystals. Past the fields, Netherwing Pass leads on to the Altar of Shadows, a lonely shrine where an ancient Shadowmoon spirit was long kept prisoner under the eye of Karsius the Ancient Watcher.', 'quest 10481 description (fields of gigantic blue crystals); warcraft.wiki.gg/wiki/Netherwing (spawned from eggs of Deathwing''s black dragonflight infused with nether energies); quest 10804 description (drakes won''t come down to feed, fall dead from exhaustion; Rocknail flayers their natural prey); quest 10870 reward text (Mordenai: my mother is free, my brothers and sisters are saved); quest 10633 description (Altar of Shadows across the fields and through Netherwing Pass); quest 10639 description and creature_text 21877 (the altar was the spirit''s prison, Karsius)'),
(352018, 1, 3520, 18, 0, 0, 'Sanctum of the Stars', 'The Sanctum of the Stars is the Scryers'' outpost in Shadowmoon, standing at the foot of the Netherwing Fields. For these blood elves the war runs on two fronts: against Illidan, and against the Sunfury of Prince Kael''thas, whose ranks keep swelling with pilgrims from Quel''Thalas. Battlemage Vyara warns that the Scryers must outrecruit Kael or, once recruits run short, outkill him. Arcanist Thelis and Larissa Sunstrike pursue Illidan''s secrets, and Varen the Reclaimer leads strikes on the Ashtongue and on the Ata''mal fel orcs, who once fell on the sanctum in a savage attack. The Dragonmaw covet the site, since it cuts their lines to Eclipse Point and Illidari Point.', 'quest 11094 description (Scryer outpost at the foot of the Netherwing Fields; lines to Eclipse Point and Illidari Point); quest 10824 description; broadcast_text 19901 (Vyara: outrecruiting Kael''thas, pilgrims from Quel''Thalas; the fight against Kael''thas and Illidan); quests 10683 (Thelis), 10687 (Larissa), 10807 and 10817 (Varen; the sanctum suffered an attack by the Ata''mal Shadowmoon orcs); zone_areas: Thelis 21955, Larissa 21954, Varen 21953, Vyara 22211 in 3938'),
(352019, 1, 3520, 19, 0, 0, 'Eclipse Point', 'Eclipse Point is a terraced ruin in the south of the valley, held by the Eclipsion, blood elves in Illidan''s service under Grand Commander Ruusk. Its dragonhawks see through disguises. The elves guard their charges closely: the Rod of Lianthe lies locked in a strongbox in a pavilion on the top tier, and they kept watch over a third of the Cipher of Damnation, moving it from place to place on Illidan''s written orders. Each day an envoy comes from the Black Temple with those orders, and from the shadows of the bridge to the north, Borak, son of Oronok, has watched the elves for weeks, waiting for a moment when the envoy''s bodyguard is gone.', 'quest 10778 description (Rod of Lianthe in a pavilion on the top tier of the ruins); quest 10577 description (disguise; Ruusk; dragonhawks see through the disguise); quest 10546 reward text and quest 10570 reward text (the third part hidden by the blood elves, kept moving by Illidan''s directive; daily envoy from the Black Temple; weeks of watching); creature_text 21409 (Envoy Icarius); zone_areas: Grand Commander Ruusk 20563, Eclipsion Dragonhawk in 3822; quest 10547 log text (the bridge north of Eclipse Point)'),
(352020, 1, 3520, 20, 0, 0, 'The Path of Conquest', 'The Path of Conquest lies just east of Eclipse Point, and there Illidan''s Eclipsion armies muster soldiers, cavaliers and spellbinders for a great advance. At its southern end, by a stationary caravan, Chancellor Bloodleaf sought to win Corok the Mighty and the giants of Shadowmoon to Illidan''s side, reminding them that Illidan''s enemies are destroyed. The crazed colossi of the Eclipsion Fields to the west are the children of Behemothon, King of the Colossi, who will not forgive an attack on them. Also at the path''s southern end stands Crimson Watch, held by the Crimson Sigil, Illidan''s elite, where Marcus Auralion, High General of the Sha''tar, was shut inside a crystal prison after Val''zareq the Conqueror captured him.', 'quests 10750, 10772 (Eclipsion armies forming at the Path of Conquest, adjacent to Eclipse Point); quests 10765, 10774 (meeting of a giant and a blood elf chancellor at the southern end near a stationary caravan); creature_text 22012, 22011 (Bloodleaf and Corok); creature_text 22054 (Behemothon: you have attacked my children, the pact is broken); quests 10769, 10776 (Eclipsion Fields, crazed colossi); quests 10793, 10815 descriptions and 10793 reward text (Crimson Watch at the southern end, Crimson Sigil, Val''zareq captured the high general, crystalline prison); zone_areas: Corok 22011, Bloodleaf 22012, Val''zareq 21979 in 3929; Crazed Colossus in 3930; Marcus Auralion 22073 in 3950; DB spawns: Ruusk (-4585, 1670), Val''zareq (-4328, 1386), Bloodleaf (-4497, 1307), Auralion (-4617, 1399)'),
(352021, 1, 3520, 21, 0, 0, 'Dragonmaw Fortress', 'Dragonmaw Fortress rises on the eastern edge of the Netherwing Fields, the stronghold of the Dragonmaw orcs who serve Illidan. Here the clan does to the nether drakes what it once did to the red dragons of Azeroth: wranglers and subjugators capture them and torture them until they bend, and many broken drakes now carry Dragonmaw drake-riders into battle. Atop the fortress, bound in chains that sap her strength, Karynaku, mate of Neltharaku and mother of the flight, is held prisoner. Her jailer is the clan''s chieftain, the ancient orc Zuluhed the Whacked, who hides in her thoughts and waits for her to break.', 'quest 10836 description (fortress on the eastern edge of the Netherwing Fields; some drakes corrupted by the Dragonmaw); npc_text 10614, 10615, 10616 (torture of captured drakes, Zuluhed and the capture of Alexstrasza, Karynaku held atop the fortress); warcraft.wiki.gg/wiki/Zuluhed_the_Whacked (Dragonmaw enslaved the red dragonflight in the Second War); quests 10858 reward text and 10866 description (chains sap her power; Zuluhed hides in her thoughts); zone_areas: Dragonmaw Wrangler, Subjugator, Drake-Rider, Enslaved Netherwing Drake, Karynaku 22112 in 3939'),
(352022, 1, 3520, 22, 0, 0, 'Netherwing Ledge', 'Netherwing Ledge was once part of the Shadowmoon mainland; now it floats in the sky off the valley''s broken southeastern shelf. It was the Netherwing''s sanctuary until the Dragonmaw took it. At Dragonmaw Base Camp, Overlord Mor''ghor drives peons and Murkblood Broken to strip the island of its crystals, ore and netherdust pollen to supply Illidan''s armies, and transporters carry the haul to the fortress along the Dragonmaw Skyway. Above the ledge the drake Vhel''kur, spawn of Deathwing, flies an endless circle around the island that was his home and is now his grave, still seething at his defeat by Teron Gorefiend.', 'quest 10634 description (once part of the mainland, now a floating island; Vhel''kur, spawn of Deathwing, defeated by Gorefiend); quest 10837 description (island off the broken shelf to the southeast); quest 11013 description (Netherwing sanctuary now home to the Dragonmaw); quests 11015-11018 (crystals, hides, pollen, ore), 11035 (Skyway transporters to Dragonmaw Fortress); npc_text 10944 (Murkblood overseer: stripping the island to supply Illidan''s armies); zone_areas: Dragonmaw Peon, Murkblood Miner in 3759; Mor''ghor 23139 in 3966; Dragonmaw Transporter in 3967'),
(352023, 1, 3520, 23, 0, 0, 'Netherwing Mines', 'The Netherwing Mines bore deep into Netherwing Ledge, where the Dragonmaw set Murkblood Broken to dig. The work stopped when a miner''s pick struck a crystal formation that turned out to be part of a sleeping nether dragon, Toranaku. The dragon woke in fury and slaughtered the workers, the creatures of the depths rose with it, and a band of miners cut off from the exit soon sank into madness. The Dragonmaw call it a grim discovery. The Murkblood know better. Offered peace and protection by the Netherwing, they helped Toranaku rouse the creatures of the mine, at great cost, hoping to make the mine unlivable and drive the orcs from the island.', 'quest 11075 description (miner struck a crystal formation attached to a sleeping nether dragon; workers annihilated); quests 11077, 11083 (creatures riled up; crazed Murkblood cut off from the exit); npc_text 10941-10946 (Murkblood overseer: the Netherwing offered peace and protection, the Murkblood helped rouse Toranaku to force the Dragonmaw off the island); zone_areas: Toranaku 23164 in 3759 near the mines; Mistress of the Mines 23149; npc_text 10943 (assisted Toranaku in rousing the creatures of this mine)'),
(352024, 2, 3520, 1, 1, 0, 'Kurdran Wildhammer', 'Kurdran Wildhammer is the thane of the Wildhammer dwarves in Outland. In the Second War he fought the Horde on the back of his gryphon, Sky''ree, and was credited with slaying nine dragons. When the Alliance expedition crossed the Dark Portal he led its gryphon riders, and when Ner''zhul''s portals began to tear Draenor apart he chose to stay behind with his comrades so that the Portal could be sealed. Azeroth mourned him as dead for twenty years. He and Sky''ree survived, and now he holds Wildhammer Stronghold against the Legion''s siege, receiving visitors inside while his keeper tends the faithful gryphon who would die for him.', 'warcraft.wiki.gg/wiki/Kurdran_Wildhammer (Second War, Sky''ree, nine dragons, Gryphon Rider Division, stayed to ensure the Portal was sealed, presumed dead twenty years, Thane of Wildhammer Stronghold); npc_text 9805 (Eli Thunderstrike on Sky''ree and Kurdran''s audiences); quest 10744 reward text'),
(352025, 2, 3520, 2, 2, 0, 'Overlord Or''barokh', 'Overlord Or''barokh commands Shadowmoon Village for the Horde, with the elite Kor''kron guard at his back. Caught between the Legion''s infernals and Illidan''s armies, he has no men to spare and says so bluntly: when a shaman came pleading for soldiers, he asked whether the shaman had no eyes for the demons at the door and advised a prayer to the gods instead, for the Horde could not help. What he does have are recruits, and every newcomer is a grunt to him. His wind riders brought word of the Eclipsion armies mustering on the Path of Conquest, and it was his plan, with a potion brewed by Researcher Tiorus, that turned the giants of Shadowmoon against Illidan''s elves.', 'quest 10595 description (elite Kor''kron guard); creature_text 21769 (What is it that you want from me, shaman? ... I do not have the soldiers to spare ... Pray to your gods); quests 10702, 10769 (grunt work; Tiorus''s concoction, Eclipsion Fields); quest 10750 description (word from his wind riders); quest 10745 reward text'),
(352026, 2, 3520, 3, 0, 0, 'Earthmender Torlok', 'Earthmender Torlok of the Earthen Ring keeps vigil at the Altar of Damnation, trying to make amends to the elements of Shadowmoon. He is an orc, and he does not hide that it was his own people who wounded them: here, he says, Gul''dan severed the tie between the orcs and the spirits, and not content with the ruin of the draenei, razed Draenor itself for power. The spirits he finds are enraged and unwilling to speak, so he gathers their souls in a totem until they can be heard. When at last they answer, they name a firelord unearthed by Gul''dan''s ritual, and Torlok, with no idea where to turn, sends for an old hermit he once met.', 'npc_text 10250 (Gul''dan severed the tie; razed Draenor); creature_text 21024 (It was my people that did this to you; Cyrukh; the fire lord); quests 10458, 10680 (the spirits are enraged and unwilling to commune with the Earthen Ring; totem of spirits); quest 10513 description (Torlok turns to Oronok, a long shot)'),
(352027, 2, 3520, 4, 0, 0, 'Oronok Torn-heart', 'Oronok Torn-heart lives as a hermit farmer above Coilskar Cistern, and admits that he has been a lot of things. One of them was a lieutenant of Gul''dan. A shaman who had abandoned the elements for shadow magic, he stood beside the warlock at the Altar of Damnation when the land was shattered, and like every orc on Draenor he felt the cut, a loss too deep for words. Sick at heart, he gathered his boys and fled to the hills. It has taken him twenty years to reach the elements again. When he learned what Illidan had done with Gul''dan''s words, he sent his three sons, Grom''tor the warrior, Ar''tor the hunter and Borak the scholar, to recover them.', 'quest 10514 description (I''ve been a lot of things); npc_text 10315, 10316, 10317, 10318 (lieutenant of Gul''dan, abandoned shamanism for shadow magic, felt the cut, fled with his boys, twenty years, sent his sons); quests 10521, 10527, 10546 (the three sons); warcraft.wiki.gg/wiki/Oronok_Torn-heart'),
(352028, 2, 3520, 5, 0, 0, 'Akama', 'Akama leads the Ashtongue, the most feared tribe of the Broken, and to many of his own people he is a traitor and Illidan''s lapdog. He lets them think so. He joined Illidan, he says, because visions foretold that his race would otherwise be destroyed, and he has waited ever since for further signs: Velen''s exodus, the opening of the Dark Portal, the coming of heroes from Azeroth. The brutes he sends to Baa''ri were chosen to keep up the mask he shows Illidan, but his Deathsworn know his true mind. Illidan holds Akama''s very soul prisoner within the Black Temple, so the Broken leader plots in secret in the Warden''s Cage, guarding Maiev Shadowsong and biding his time.', 'npc_text 10447 (known as a traitor, Illidan''s lapdog); quest 10619 description (Ashtongue feared among all Broken); quest 10628 reward text (visions, Velen''s exodus, the Dark Portal, your arrival); quest 10622 description (Baa''ri Ashtongue hand-picked to maintain the facade; Deathsworn know his intentions); quest 10948 description (his soul held prisoner inside the Black Temple); creature_text 21700 (keeping the secret, Maiev)'),
(352029, 2, 3520, 6, 0, 0, 'Maiev Shadowsong', 'Maiev Shadowsong is the Warden who held Illidan captive for ten thousand years and hunted him all the way to Outland after he escaped. Now she is the prisoner, locked in a cell in the Warden''s Cage under the watch of Akama and his Deathsworn. Akama insists that they want the same thing and that she must wait, for he has spent years preparing and cannot tip his hand too soon. Maiev will have none of it. She is no pawn in his game, she tells him, and when she unleashes her wrath on Illidan it will have nothing to do with his foolish scheme. If Illidan is to die, it will be by her hand.', 'creature_text 21699 (release me; if Illidan is to die it shall be by my hand; not a pawn in your game; cell won''t hold me); creature_text 21700 (In due time, Maiev; years preparing); warcraft.wiki.gg/wiki/Akama (Akama became Maiev''s jailer); Warcraft III: The Frozen Throne (Maiev as Illidan''s jailer for ten thousand years, pursued him to Outland); warcraft.wiki.gg/wiki/Maiev_Shadowsong (guarded Illidan ten thousand years; pursued him to Outland; held in the Warden''s Cage)'),
(352030, 2, 3520, 7, 0, 0, 'Neltharaku', 'Neltharaku is the patron of the Netherwing, a nether dragon who flies high above the Netherwing Fields, where his young dare not land for fear of the Dragonmaw. He is a father in grief. The orcs have taken many of his children to Dragonmaw Fortress and tortured them until they gave in, and his mate Karynaku is chained atop its walls; every attempt he has made to free her has failed. Neltharaku feels powerless against them. It was Illidan, he says, who found the Dragonmaw their leader, Zuluhed, the orc held responsible for the capture of the Dragon Aspect Alexstrasza. If such an orc could take an Aspect, how could the young Netherwing resist him?', 'quest 10811 description (patron soars high above); npc_text 10614, 10615, 10616 (Neltharaku''s tale: torture at the fortress, refusal to land, Illidan delivered Zuluhed, Alexstrasza, Karynaku and failed rescues); quest 10858 description (without my mate the brood may die out)'),
(352031, 2, 3520, 8, 0, 0, 'Overlord Mor''ghor', 'Overlord Mor''ghor rules the Dragonmaw Base Camp on Netherwing Ledge, a coarse and boastful fel orc who serves Illidan and drives his workers to strip the island bare. He was once a chief lieutenant of the Dragonmaw at Grim Batol on Azeroth, a past the black dragonflight has not forgotten. Recruits who arrive with service papers start as peons, and the few who survive rise in rank under his eye. He sends his captains against the Legion on the Twilight Ridge and his commanders against the Aldor and the Scryers. He also keeps dealings of his own: the Netherwing eggs his orcs collect are sought by Lady Sinestra, who speaks for a black dragon master Mor''ghor had believed dead.', 'quest 11013 description and reward text (service papers, peon); creature_text 23284 (Lady Sinestra: chief lieutenant at Grim Batol; the Netherwing eggs; my master) and 23139 (The master? He lives?); quests 11086, 11094, 11099 (Twilight Ridge, sacking the Scryer and Aldor outposts); npc_text 10944 (the Dragonmaw strip the island and supply Illidan''s armies); warcraft.wiki.gg/wiki/Overlord_Mor''ghor (BC section)'),
(352032, 2, 3520, 9, 0, 0, 'Illidari Lord Balthas', 'Illidari Lord Balthas is an eredar in Illidan''s service who stands among the Dragonmaw at their base camp on Netherwing Ledge. His brother, Reth''hedron the Subduer, chose the other side and now lords over the Twilight Ridge in Nagrand for the Burning Legion. With the Sha''tar bringing war to the gates of the Black Temple, Balthas admits that the Illidari cannot spare the strength to slay an eredar of his brother''s power. He has a colder answer instead: a soul cannon attuned to his own blood, which is also Reth''hedron''s, to drive his brother back through the Twilight Portal. Reth''hedron will return, Balthas warns, but the Legion''s war is weakened for now.', 'quest 11089 description (Reth''hedron lords over the Twilight Ridge; no resources to slay him with the war the Sha''tar brought to the Black Temple; banish him through the portal); quest 11090 description and reward text (soul cannon attuned to his blood, my brother; he will be back); data/lore/nagrand.json 351820 (Reth''hedron is an eredar; Twilight Ridge place told there); warcraft.wiki.gg/wiki/Illidari_Lord_Balthas (Man''ari eredar, brother Reth''hedron)'),
(352033, 2, 3520, 10, 0, 0, 'Doomwalker', 'Doomwalker is a fel reaver unlike any other, a towering war engine of the Burning Legion that Kil''jaeden sent to assault the gates of the Black Temple. The tales say it was infused with the captured souls of martyred draenei, which set it apart from the lesser reavers of Outland. It prowls the approaches before the temple and greets intruders in a cold, mechanical voice, warning them to proceed no farther or be eliminated. When it strikes, it speaks of tectonic disruption and the ground trembles, and over each fallen foe it pronounces the same verdict: threat level zero, directive accomplished.', 'warcraft.wiki.gg/wiki/Doomwalker (fel reaver sent by Kil''jaeden to assault the gates of the Black Temple, built with captured draenei souls); creature_text 17711 (Do not proceed; tectonic disruption; threat level zero; directive accomplished); DB spawn 84633 at (-3563, 234), area 3520 north of the Black Temple grounds; warcraft.wiki.gg/wiki/Doomwalker (infused with the captured souls of martyred draenei)'),
(352034, 3, 3520, 1, 0, 0, 'The Legion''s Bombardment', 'Infernals fall on Wildhammer Stronghold and Shadowmoon Village day and night, flung from Legion Hold, and the defenders of both outposts are close to breaking. Wing Commander Nuainn and Blood Guard Gulmok each send a volunteer into the hold in disguise to listen at the Legion''s communication device. The news is grim: Warbringer Razuun, speaking for Doom Lord Kazzak, orders the attacks increased and promises infernals enough from the Deathforge. A bomb built from a dead fel reaver''s power core destroys the stockpile in the hold. Scouts at Deathforge Tower and Slag Watch then guide the assault on the forge itself, where the summoning ritual is broken and Razuun is slain. His orders point to the true staging ground, Invasion Point: Cataclysm, reached by a teleporter. There Plexi, for the Alliance, and Nakansi, for the Horde, rig a captured fel reaver to smash the Legion''s own infernals, and word of the broken siege goes back to Kurdran and Or''barokh.', 'quests 10562-10589, 10766, 10606, 10612, 10744 (Alliance chain); quests 10595-10604, 10767, 10611, 10613, 10745 (Horde chain); creature_text 21502, 21633 (Razuun and Jovaan at the communication device)'),
(352035, 3, 3520, 2, 0, 0, 'The Cipher of Damnation', 'At the Altar of Damnation the Earthen Ring sets out to heal Shadowmoon''s tortured elements. With a totem of spirits, Earthmender Torlok gathers the souls of enraged fire, earth, water and air, and when the spirits finally speak they name Cyrukh the Firelord, an elemental lord unearthed by Gul''dan''s ritual. Only the ritual''s own words can call him forth. Torlok sends for the hermit Oronok Torn-heart, who confesses that he was Gul''dan''s lieutenant: Illidan found those words, the Cipher of Damnation, in the Black Temple and split them among his servants. Oronok''s sons go after the pieces. Grom''tor beats one hiding place out of a Coilskar naga. Ar''tor is found dead at Illidari Point, yet his spirit wins back his family bow and the second piece from Veneratus the Many. Borak baits Illidan''s envoy with bloodthistle, delivers false orders into Eclipse Point, and ambushes Ruul the Darkener for the third. Read whole at the altar, the cipher calls Cyrukh, and the firelord falls.', 'quests 10680/10681 (breadcrumbs to Torlok), 10458, 10480, 10481 and creature_text 21024 (spirits name Cyrukh, an elemental lord unearthed); quests 10513-10519, npc_text 10313-10318 (Oronok''s story); quests 10521-10523 (Grom''tor), 10527-10541 (Ar''tor, Lohn''goron, Veneratus), 10546-10579 (Borak, bloodthistle, Icarius, Ruusk, Ruul); quest 10588 (reading the cipher at the Altar of Damnation, Cyrukh)'),
(352036, 3, 3520, 3, 0, 0, 'The Return of Teron Gorefiend', 'The ghosts of Shadowmoon have grown restless. Zorus the Judicator at Wildhammer Stronghold and Chief Apothecary Hildagard at Shadowmoon Village craft goggles from ever-burning ash that let their wearers see the dead, and the spirits cleared from both outposts whisper one name: Teron Gorefiend, Gul''dan''s warlock, whose soul was bound into a slain knight''s body to make the first death knight of the Horde. The trail leads to an ancient Shadowmoon spirit at the Altar of Shadows, who claims Gorefiend took his own life after the Second War and offers to divine his fate if his relics are found. His armor lies with Vhel''kur over Netherwing Ledge, his cloak with the ghosts of the clerics he murdered at Karabor, his truncheon with the Ghostriders who rose from his slain death knights. Once all three are gathered, the spirit drops its mask. It is Gorefiend himself, imprisoned at the altar, and he seizes his helper''s body to slay his jailer, Karsius, and walks free once more.', 'quests 10642, 10643, 10644, 10645 (Alliance, Zorus) and 10624, 10625, 10633, 10639 (Horde, Hildagard); quest 10625 reward text (Gorefiend slain by Doomhammer, soul placed in a slain knight of Stormwind, first death knight); quests 10633, 10634, 10635, 10636 (the spirit''s account, Vhel''kur, clerics of Karabor, Ghostriders); quest 10639 description; creature_text 21797, 21872, 21877 (possession, Karsius, Gorefiend has returned)'),
(352037, 3, 3520, 4, 0, 0, 'The Medallion of Karabor', 'The Aldor at the Altar of Sha''tar and the Scryers at the Sanctum of the Stars both learn that the Ashtongue are digging in the Ruins of Baa''ri, and both send agents to seize the Tablets of Baa''ri first. The tablets speak of a Medallion of Karabor, which once let the highest draenei priests enter the temple freely. Orders taken from Oronu the Elder reveal that four fragments of it went to the Ashtongue Corruptors, and once those are won, the trail leads to Akama himself in the Warden''s Cage. There his second, Sanoru, admits that Akama has been watching. After the satyr spy Zandras is slain, the visitor is led through a hidden passage to Akama, who confesses that he serves Illidan only in appearance and that the fragments were replicas: he holds the true medallion, still missing its last piece. That search leads into the Arcatraz, onto the Ata''mal Terrace for the Heart of Fury, and at last to A''dal in Shattrath.', 'quests 10568, 10571, 10574, 10575 (Aldor) and 10683, 10684, 10685, 10686 (Scryers); quests 10622, 10628 (Sanoru, Zandras, Akama); quests 10705, 10706, 10707, 10708 (replicas, Udalo in the Arcatraz, Heart of Fury, A''dal); creature_text 21700 (Heart of Fury, take it to A''dal)'),
(352038, 3, 3520, 5, 0, 0, 'Illidan''s Pupil', 'Aldor and Scryer scouts alike report Sunfury recruits streaming into the Ruins of Karabor, dressed and fighting like Illidan himself. Glaives taken from the initiates confirm the fear: Illidan is training blood elf demon hunters. While the pit lord Azaloth, loosed on his captors, keeps the grounds in chaos, Exarch Onaala and Larissa Sunstrike send their agent to Nagrand to seek Altruis the Sufferer, a demon hunter who bears Illidan no allegiance. Altruis tells the tale of Varedis. Of five warriors Kael''thas sent to Illidan, three died in training and one went mad; Varedis alone survived and soon surpassed the three masters set to teach him. He had stolen into the Shadow Council and learned by heart the Book of Fel Names, said to hold the true name of every demon. After proving themselves to Altruis, the agents take the book from the Shadow Labyrinth, and when Varedis takes his demon form at Karabor it is burned before him, stripping his power as he and his masters fall.', 'quests 10587, 10637, 10640, 10650, 10651 (Aldor) and 10687, 10688, 10689, 10691, 10692 (Scryers); npc_text 10492-10497 (Altruis''s account of Varedis); quests 10641, 10646, 10649, 10668, 10669 (Altruis''s trials and the Book of Fel Names)'),
(352039, 3, 3520, 6, 0, 0, 'The Plight of the Netherwing', 'Mordenai finds the nether drakes over the Netherwing Fields starving, too frightened to land, and asks for help feeding them flayer carcasses. That kindness reaches their patron, Neltharaku, who tells of Dragonmaw Fortress, where the Dragonmaw torture captured drakes into obedience, and of his mate Karynaku, chained atop its walls. To buy him time, the orcs in the fortress are cut down while he devises a remedy. From nethervine crystals gathered on Netherwing Ledge he makes charms filled with his own essence, which break the riders'' hold over their enslaved drakes and set them free to turn on their captors. Then comes the climb to the top of the fortress. Karynaku, weakened by her chains, calls Zuluhed the Whacked to her with a false promise to obey, and when the old chieftain appears he is slain for his key. Freed at last, she carries her rescuer back to Mordenai, who names the stranger kin to the Netherwing Dragonflight.', 'quests 10804, 10811, 10814, 10836, 10837, 10854, 10858, 10866, 10870/10871; npc_text 10614-10616 (Neltharaku''s tale); creature_text 11980 (Zuluhed)'),
(352040, 3, 3520, 7, 0, 0, 'Among the Dragonmaw', 'Sworn by blood oath to the Netherwing, an ally is cloaked by the flight''s magic as a fel orc and sent to Netherwing Ledge with service papers for Overlord Mor''ghor, who laughs and makes the newcomer a peon. Daily labor for Taskmaster Varkule covers the true work, done for Yarzill the Merc, a Netherwing agent in disguise: poisoning peon camps, ambushing transporters on the Dragonmaw Skyway, and hunting stolen Netherwing eggs. The infiltrator rises to overseer, captain and commander. Ordered to sack the Aldor or Scryer outpost, the commander warns them instead, and their defenders spring a trap on the Dragonmaw raiders while Mor''ghor is shown medals as proof of victory. At last Mor''ghor names his finest orc the first highlord of the Dragonmaw, and Illidan himself comes to the ledge to see this hero. He sees through the disguise at once and declares the whole operation compromised. Yarzill snatches the highlord to safety, and the Netherwing''s thanks wait with Barthamus in Shattrath.', 'quests 11012, 11013, 11014, 11019, 11020, 11035, 11049, 11053, 11084, 11092, 11094/11099, 11095/11100, 11097/11101, 11107, 11108; creature_text 23139, 22083, 23141 (Mor''ghor, Illidan, Yarzill at the highlord ceremony); quest 11019 reward text (Yarzill''s eyes flicker blue: we are here with you)'),
(352041, 3, 3520, 8, 0, 0, 'The Dark Conclave', 'Journal pages taken from the arakkoa ghosts of the Sketh''lon Wreckage, by Gryphonrider Kieran''s agents for the Alliance or Sergeant Kargrul''s for the Horde, speak of a spell gone awry and of a deserter. The deserter is Parshah, a haunted arakkoa waiting by the road through the Magma Fields. He tells how his people, seeing the Horde mass under Gul''dan, prepared to strike him first, and how the warlock answered with magic that destroyed their camps and twisted their spirits. Worse, Gul''dan''s power fed on the arakkoa''s own spell, and the ghosts of the Dark Conclave now seek to summon an ancient evil in the lava pits south of their base camp. Parshah builds a staff to stop them from Asghar''s war totem, the Rod of Lianthe taken from Eclipse Point and Sketh''lon feathers, its headpiece charged with the echoes of Gul''dan at the Altar of Damnation. With it the ritual is broken, and Parshah at last believes he was right to desert.', 'quests 10569, 10759 (Alliance) and 10760, 10761 (Horde); quests 10777, 10778, 10780, 10782, 10808 (Parshah''s staff and the ritual); npc_text 10556 (Parshah''s gaze)'),
(352042, 3, 3520, 9, 0, 0, 'The Illidari-Bane Blade', 'Shards of a strange metal turn up among the mo''arg of Legion Hold, etched with glowing runes. Ordinn Thunderfist at Wildhammer Stronghold and Grokom Deatheye at Shadowmoon Village know the work: a rare ore enchanted to destroy demons, a secret weapon the Legion means to use against Illidan''s forces. More of the metal is taken from the glaives of the pit lords Makazradon and Morgroron, but forging it is beyond either smith. Both send the ingots to David Wayne, a blacksmith who came to Draenor with the Sons of Lothar and later left the expedition to live alone in Terokkar Forest; even Grokom admits it pains him to send Horde business to a human. Wayne needs rare things: an overcharged manacell from the Mechanar, the Lexicon Demonica from the Shadow Labyrinth, underworld loam from the Steamvault and the Tear of the Earthmother from the Shattered Halls. The finished sword is quenched in the Scalding Pools of the Hand of Gul''dan, a blade to cut down Illidari and Legion demons alike.', 'quests 10621, 10626, 10662 (Alliance) and 10623, 10627, 10663 (Horde); quests 10664, 10665, 10666, 10667, 10670, 10676, 10679 (David Wayne''s materials, quenching at the Scalding Pools); npc_text 10500 (David Wayne and the Sons of Lothar)');
